function codeToAlgorithm(line, language = 'python') {
  // Convert code statements to algorithmic descriptions
  
  // Print/Output statements
  if (/print\(|console\.log\(|System\.out\.println\(|printf\(|cout\s*<</.test(line)) {
    const content = line.match(/["'](.*?)["']|print\((.*?)\)|console\.log\((.*?)\)/);
    if (content) {
      const msg = content[1] || content[2] || content[3] || 'message';
      return `Display "${msg}"`;
    }
    return 'Display output';
  }
  
  // Function/Method definitions
  if (/^def\s+(\w+)|^function\s+(\w+)|^static\s+void\s+(\w+)|^void\s+(\w+)/.test(line)) {
    const funcMatch = line.match(/(?:def|function|void)\s+(\w+)/);
    const funcName = funcMatch ? funcMatch[1] : 'function';
    return `Start ${funcName}`;
  }
  
  // Conditional statements
  if (/^if\s+/.test(line)) {
    let condition = line.replace(/^if\s+/, '').replace(/[:\{].*$/, '').trim();
    // Simplify condition
    condition = condition
      .replace(/num\s*%\s*2\s*==\s*0/g, 'number is even')
      .replace(/num\s*%\s*2\s*!=\s*0/g, 'number is odd')
      .replace(/===|==/g, 'equals')
      .replace(/!=|!==/g, 'not equals')
      .replace(/&&/g, 'and')
      .replace(/\|\|/g, 'or')
      .replace(/\(/g, '').replace(/\)/g, '');
    return `Is ${condition}?`;
  }
  
  if (/^elif\s+/.test(line)) {
    let condition = line.replace(/^elif\s+/, '').replace(/[:\{].*$/, '').trim();
    condition = condition
      .replace(/num\s*%\s*2\s*==\s*0/g, 'number is even')
      .replace(/===|==/g, 'equals');
    return `Else if ${condition}?`;
  }
  
  if (/^else[:\{]?/.test(line)) {
    return 'Otherwise';
  }
  
  // Loop statements
  if (/^for\s+/.test(line)) {
    const loopMatch = line.match(/for\s+.*?in\s+range\((\d+)\)|for\s*\(.*?<\s*(\d+)/);
    const count = loopMatch ? (loopMatch[1] || loopMatch[2]) : 'N';
    return `Repeat ${count} times`;
  }
  
  if (/^while\s+/.test(line)) {
    let condition = line.replace(/^while\s+/, '').replace(/[:\{].*$/, '').trim();
    return `While ${condition}`;
  }
  
  // Return statements
  if (/^return\b/.test(line)) {
    const value = line.replace(/^return\s*/, '').replace(/;.*$/, '').trim();
    return value ? `Return ${value}` : 'Return';
  }
  
  // Function calls
  if (/(\w+)\(/.test(line) && !line.startsWith('if') && !line.startsWith('for') && !line.startsWith('while')) {
    const funcMatch = line.match(/(\w+)\(/);
    const funcName = funcMatch ? funcMatch[1] : 'function';
    return `Call ${funcName}`;
  }
  
  // Variable assignments
  if (/=/.test(line) && !/==|!=/.test(line)) {
    const varMatch = line.match(/(\w+)\s*=\s*(.+)/);
    if (varMatch) {
      return `Set ${varMatch[1]} to ${varMatch[2].replace(/;.*$/, '').trim()}`;
    }
  }
  
  // Default: clean up the line
  return line.replace(/[;\{\}]/g, '').trim();
}

export function parseToGraph(code) {
  const lines = code
    .split("\n")
    .map(l => l.trim())
    .filter(l => l.length && !l.startsWith("#") && !l.startsWith("//"));

  let nodes = [];
  let edges = [];
  let stack = [];
  let id = 1;
  
  // Detect language
  let language = 'python';
  if (/function\s+\w+|console\.log|let\s+|const\s+/.test(code)) language = 'javascript';
  else if (/System\.out\.println|public\s+static/.test(code)) language = 'java';
  else if (/#include|printf|cout/.test(code)) language = 'c';

  function addNode(text, type = "process") {
    const algorithmText = codeToAlgorithm(text, language);
    const node = { id: id++, text: algorithmText, type };
    nodes.push(node);
    return node;
  }

  let prev = null;

  for (let line of lines) {
    let currentType = "process";
    let node = null;

    // Detect key structures
    if (/^if\s+/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      stack.push(node);
    } else if (/^elif\s+/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      edges.push({ from: stack[stack.length - 1].id, to: node.id, label: "No" });
      stack.push(node);
    } else if (/^else[:\{]?/.test(line)) {
      currentType = "decision";
      node = addNode(line, currentType);
      edges.push({ from: stack[stack.length - 1].id, to: node.id, label: "No" });
      stack.push(node);
    } else if (/^(for|while)\s+/.test(line)) {
      currentType = "loop";
      node = addNode(line, currentType);
      stack.push(node);
    } else if (/^def\s+|^function\s+|^static\s+void\s+|^void\s+/.test(line)) {
      currentType = "function";
      node = addNode(line, currentType);
    } else if (/^return\b/.test(line)) {
      currentType = "return";
      node = addNode(line, currentType);
    } else {
      node = addNode(line);
    }

    if (prev) {
      // connect normal flow
      const lastEdge = edges[edges.length - 1];
      if (!lastEdge || lastEdge.to !== node.id) {
        edges.push({ from: prev.id, to: node.id, label: prev.type === 'decision' ? 'Yes' : '' });
      }
    }

    prev = node;
  }

  return { nodes, edges };
}

